class SSHWorker(QThread):
    progress_updated = pyqtSignal(int)
    output_received = pyqtSignal(str)
    finished = pyqtSignal(bool, str)
    url_generated = pyqtSignal(str)

    def __init__(self, hostname, username, password, root_password):
        super().__init__()
        self.hostname = hostname
        self.username = username
        self.password = password
        self.root_password = root_password
        self.is_running = True
        self.detected_ip = ""

    def run(self):
        try:
            # Connect to server
            self.output_received.emit("⌛ Connecting to server...")
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(
                self.hostname,
                username=self.username,
                password=self.password,
                timeout=30
            )
            self.progress_updated.emit(5)

            # Create installation file
            self.output_received.emit("⚙️ Creating installation script...")
            script = self.generate_install_script()
            sftp = ssh.open_sftp()
            remote_path = "/tmp/zabbix_install.sh"
            with sftp.file(remote_path, 'w') as remote_file:
                remote_file.write(script)
            sftp.chmod(remote_path, 0o755)  # Make executable
            sftp.close()
            self.progress_updated.emit(10)

            # Execute script as root
            self.output_received.emit("🚀 Starting installation (requires root privileges)...")
            command = f"echo '{self.root_password}' | sudo -S bash {remote_path}"
            self.progress_updated.emit(15)

            # Execute commands and monitor output
            channel = ssh.get_transport().open_session()
            channel.exec_command(command)
            self.monitor_ssh_channel(channel, ssh, remote_path)

        except Exception as e:
            self.output_received.emit(f"❌ Error: {str(e)}")
            self.finished.emit(False, str(e))

    def generate_install_script(self):
        return """#!/bin/bash
# Basic updates
sudo apt update && sudo apt upgrade -y

# Install Zabbix repository
wget https://repo.zabbix.com/zabbix/7.4/release/ubuntu/pool/main/z/zabbix-release/zabbix-release_latest_7.4+ubuntu24.04_all.deb
sudo dpkg -i zabbix-release_latest_7.4+ubuntu24.04_all.deb
sudo apt update -y

# Install Zabbix packages
echo 'Y' | sudo apt install zabbix-server-mysql zabbix-frontend-php zabbix-apache-conf zabbix-sql-scripts zabbix-agent -y

# Install MySQL
sudo apt install mysql-server -y

# Configure database
sudo mysql -u root -e "CREATE DATABASE zabbix CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;"
sudo mysql -u root -e "CREATE USER zabbix@localhost IDENTIFIED BY 'password';"
sudo mysql -u root -e "GRANT ALL PRIVILEGES ON zabbix.* TO zabbix@localhost;"
sudo mysql -u root -e "SET GLOBAL log_bin_trust_function_creators = 1;"

# Import Zabbix data
zcat /usr/share/zabbix/sql-scripts/mysql/server.sql.gz | mysql --default-character-set=utf8mb4 -uzabbix -ppassword zabbix

# Reset MySQL settings
sudo mysql -u root -e "SET GLOBAL log_bin_trust_function_creators = 0;"

# Configure Zabbix Server
sudo sed -i "s/^# DBPassword=/DBPassword=password/" /etc/zabbix/zabbix_server.conf

# Restart services
sudo systemctl restart zabbix-server zabbix-agent apache2
sudo systemctl enable zabbix-server zabbix-agent apache2

# Get IP address
IP=$(hostname -I | awk '{print $1}')
echo "✅ Installation completed successfully! Access URL: http://$IP/zabbix/"
"""

    def monitor_ssh_channel(self, channel, ssh, remote_path):
        output_buffer = ""
        while not channel.exit_status_ready() and self.is_running:
            time.sleep(0.5)
            if channel.recv_ready():
                data = channel.recv(1024).decode('utf-8')
                output_buffer += data
                self.output_received.emit(data)
                
                # Update progress based on output content
                if "apt update" in output_buffer:
                    self.progress_updated.emit(20)
                elif "zabbix-release" in output_buffer:
                    self.progress_updated.emit(30)
                elif "zabbix-server-mysql" in output_buffer:
                    self.progress_updated.emit(50)
                elif "mysql-server" in output_buffer:
                    self.progress_updated.emit(60)
                elif "CREATE DATABASE" in output_buffer:
                    self.progress_updated.emit(70)
                elif "zcat" in output_buffer:
                    self.progress_updated.emit(80)
                elif "systemctl restart" in output_buffer:
                    self.progress_updated.emit(90)
                    
                # Detect URL in output
                url_match = re.search(r'http://\d+\.\d+\.\d+\.\d+/zabbix/', output_buffer)
                if url_match:
                    self.detected_ip = url_match.group(0)
                    
                # Detect errors
                if any(err in output_buffer.lower() for err in ["error", "fail"]):
                    self.output_received.emit("⚠️ Potential error detected!")
                    
                # Periodically clear buffer
                if len(output_buffer) > 10000:
                    output_buffer = output_buffer[-5000:]

        # Final cleanup
        ssh.exec_command(f"sudo rm -f {remote_path}")
        exit_status = channel.recv_exit_status()
        ssh.close()
        
        if exit_status == 0:
            if self.detected_ip:
                self.url_generated.emit(self.detected_ip)
            self.finished.emit(True, "Installation completed successfully!")
        else:
            self.finished.emit(False, f"Installation failed with exit code: {exit_status}")

    def stop(self):
        self.is_running = False

